    const v1x = cx - ax, v1y = cy - ay, v2x = bx - cx, v2y = by - cy;
    const cr = v1x * v2y - v1y * v2x, d1 = Math.hypot(v1x, v1y), d2 = Math.hypot(v2x, v2y);
