        const [bpx, bpy] = front(52 * sc, -30 * sc);
        boxCol(ctx, bpx, bpy, z, 1.4 * sc, 1.4 * sc, 26 * sc, frontAng, "#8A8A8A", sun, 0.2);
        const [bsx, bsy] = R.P(bpx, bpy, z + 40 * sc), brr = 13 * sc * R.zoom;
