        ctx.fillStyle = "#D8352A"; ctx.beginPath(); ctx.ellipse(bsx, bsy + brr * 1.3, brr * 0.5, brr * 0.28, 0, 0, TAU); ctx.fill();
        glow(bpx, bpy, z + 40 * sc, 22 * sc, "rgba(255,200,120,.3)");
